// @ts-check
import { deleteImage, saveImage } from "./branding-image.js";

/** Only names generated by `saveLogo` are ever read back, deleted or exposed. */
export const LOGO_FILE_RE = /^logo-[0-9a-f-]{36}\.(png|jpg|webp|svg)$/;

/** @type {import('./branding-image.js').ImageKind} */
const KIND = { prefix: "logo", fileCol: "logoFile", re: LOGO_FILE_RE };

/**
 * @param {number} id
 * @param {{ userId: number, nickname: string }} consumer
 * @param {{ buffer: Buffer, ext: string }} logo
 */
export const saveLogo = (id, consumer, logo) =>
  saveImage(KIND, id, consumer, logo);

/**
 * @param {number} id
 * @param {{ userId: number, nickname: string }} consumer
 */
export const deleteLogo = (id, consumer) => deleteImage(KIND, id, consumer);
